from gen import *
V="verb"; N="noun"; A="adjective"; AD="adverb"; P="phrase"; C="conjunction"
T(68,1,"Порівнюємо: -er","Порівнювати короткі прикметники.",
 "До коротких прикметників додаємо -er і слово than («ніж»): tall — taller than, short — shorter than, fast — faster than, slow — slower than, long — longer than. Приклад: My brother is taller than me. The train is faster than the bus.",
 [W("taller","/ˈtɔːlə/",A,"вищий","My brother is taller than me.","Мій брат вищий за мене."),
  W("shorter","/ˈʃɔːtə/",A,"нижчий, коротший","This road is shorter.","Ця дорога коротша."),
  W("faster","/ˈfɑːstə/",A,"швидший","The train is faster than the bus.","Потяг швидший за автобус."),
  W("slower","/ˈsləʊə/",A,"повільніший","The bus is slower.","Автобус повільніший."),
  W("longer","/ˈlɒŋɡə/",A,"довший","The film is longer than the book.","Фільм довший за книжку.")],
 ("Tell me about her.","Повторимо. Вона письменниця. Що відповісти?",["She was a famous writer.","She were famous writer.","She is a writer was."],"She was a famous writer."),
 [("My brother is taller than me.","Прослухайте. Хто вищий?",["Брат","Я","Обидва однакові"],"Taller."),
  ("The train is faster than the bus.","Прослухайте. Що швидше?",["Потяг","Автобус","Однаково"],"Faster."),
  ("The film is longer than the book.","Прослухайте. Що довше?",["Фільм","Книжка","Однаково"],"Longer.")],
 [("My brother is ___ than me.",["taller","tall","tallest"],"Taller than."),
  ("The train is ___ than the bus.",["faster","fast","more fast"],"Faster than."),
  ("This road is ___ than that one.",["shorter","short","more short"],"Shorter than.")],
 ("Яка форма від slow?",["slower","more slow","slowest"],"Slow — slower."),
 ("Мій брат вищий за мене.",["My","brother","is","taller","than","me"],["tall","as"],"My brother is taller than me."),
 ("Потяг швидший за автобус.",["The train is faster than the bus"],"The train is faster than the bus."),
 ("Which is faster, the train or the bus?","Потяг. Що відповісти?",["The train is faster.","The train is more fast.","The train fast than bus."],"The train is faster."))
T(68,2,"Правила написання","Правильно писати форми -er.",
 "Якщо прикметник закінчується на -e, додаємо тільки -r: nice — nicer, large — larger, safe — safer. Одна голосна + одна приголосна — подвоюємо: thin — thinner, hot — hotter. Приголосна + y — -ier: easy — easier.",
 [W("nicer","/ˈnaɪsə/",A,"приємніший","This room is nicer.","Ця кімната приємніша."),
  W("larger","/ˈlɑːdʒə/",A,"більший","The second flat is larger.","Друга квартира більша."),
  W("thinner","/ˈθɪnə/",A,"тонший, худіший","This book is thinner.","Ця книжка тонша."),
  W("hotter","/ˈhɒtə/",A,"спекотніший","Today is hotter than yesterday.","Сьогодні спекотніше, ніж учора."),
  W("easier","/ˈiːziə/",A,"легший","This exercise is easier.","Ця вправа легша.")],
 ("Which is faster, the train or the bus?","Повторимо. Потяг. Що відповісти?",["The train is faster.","The train is more fast.","The train fast than bus."],"The train is faster."),
 [("This room is nicer.","Прослухайте. Що каже людина?",["Ця кімната приємніша","Ця кімната більша","Ця кімната дорожча"],"Nicer."),
  ("Today is hotter than yesterday.","Прослухайте. Коли було спекотніше?",["Сьогодні","Учора","Однаково"],"Hotter."),
  ("This exercise is easier.","Прослухайте. Яка вправа?",["Легша","Складніша","Довша"],"Easier.")],
 [("This room is ___.",["nicer","niceer","more nice"],"Nice — nicer."),
  ("Today is ___ than yesterday.",["hotter","hoter","more hot"],"Hot — hotter."),
  ("This exercise is ___.",["easier","easyer","more easy"],"Easy — easier.")],
 ("Яка форма від thin?",["thinner","thiner","more thin"],"Thin — thinner."),
 ("Ця вправа легша.",["This","exercise","is","easier"],["easy","are"],"This exercise is easier."),
 ("Сьогодні спекотніше, ніж учора.",["Today is hotter than yesterday"],"Today is hotter than yesterday."),
 ("Is the second flat bigger?","Так, більша. Що відповісти?",["Yes, it is larger.","Yes, it is more large.","Yes, it larger is."],"Yes, it is larger."))
T(68,3,"Однаково чи по-різному","Говорити про схожість і різницю.",
 "As … as — «такий самий … як»: He is as tall as me. The same as — той самий: the same as yours. Different from — відмінний від, similar to — схожий на, compare — порівнювати. Приклад: My phone is similar to yours.",
 [W("as ... as","/æz ... æz/",P,"так само … як","He is as tall as me.","Він такий самий високий, як я."),
  W("the same as","/ðə ˈseɪm əz/",P,"той самий, що й","My bag is the same as yours.","Моя сумка така сама, як твоя."),
  W("different from","/ˈdɪfrənt frəm/",P,"відмінний від","My phone is different from yours.","Мій телефон відрізняється від твого."),
  W("similar to","/ˈsɪmələ tə/",P,"схожий на","This coat is similar to mine.","Це пальто схоже на моє."),
  W("compare","/kəmˈpeə/",V,"порівнювати","Compare the two photos.","Порівняйте дві фотографії.")],
 ("Is the second flat bigger?","Повторимо. Так, більша. Що відповісти?",["Yes, it is larger.","Yes, it is more large.","Yes, it larger is."],"Yes, it is larger."),
 [("He is as tall as me.","Прослухайте. Що каже людина?",["Він такого самого зросту, як я","Він вищий за мене","Він нижчий за мене"],"As tall as."),
  ("My bag is the same as yours.","Прослухайте. Що каже людина?",["Її сумка така сама, як твоя","Її сумка інша","Її сумка більша"],"The same as."),
  ("Compare the two photos.","Прослухайте. Що треба зробити?",["Порівняти фотографії","Зробити фотографії","Показати фотографії"],"Compare.")],
 [("He is ___ tall as me.",["as","than","the"],"As … as."),
  ("My phone is different ___ yours.",["from","than","as"],"Different from."),
  ("This coat is similar ___ mine.",["to","from","as"],"Similar to.")],
 ("Що означає the same as?",["такий самий, як","відмінний від","схожий на"],"The same as."),
 ("Він такий самий високий, як я.",["He","is","as","tall","as","me"],["than","taller"],"He is as tall as me."),
 ("Моя сумка така сама, як твоя.",["My bag is the same as yours"],"My bag is the same as yours."),
 ("Is your phone like mine?","Схожий. Що відповісти?",["Yes, it's similar to yours.","Yes, it is similar with yours.","Yes, it similar yours."],"Yes, it's similar to yours."))
T(68,4,"Скільки різниці","Описати розмір різниці.",
 "Slightly — трохи, even — навіть, twice as … as — удвічі більший, half as … as — вдвічі менший, а ще ви знаєте much і a bit. Приклад: This is slightly cheaper. It's even bigger. It is twice as expensive.",
 [W("slightly","/ˈslaɪtli/",AD,"трохи","It's slightly cheaper.","Це трохи дешевше."),
  W("even","/ˈiːvn/",AD,"навіть","It's even bigger.","Воно навіть більше."),
  W("twice as","/ˈtwaɪs əz/",P,"удвічі більше","It's twice as expensive.","Це вдвічі дорожче."),
  W("half as","/ˈhɑːf əz/",P,"удвічі менше","It's half as long.","Це вдвічі коротше."),
  W("either","/ˈaɪðə/",AD,"також (у запереченні)","I don't like it either.","Мені це теж не подобається.")],
 ("Is your phone like mine?","Повторимо. Схожий. Що відповісти?",["Yes, it's similar to yours.","Yes, it is similar with yours.","Yes, it similar yours."],"Yes, it's similar to yours."),
 [("It's slightly cheaper.","Прослухайте. Що каже людина?",["Це трохи дешевше","Це вдвічі дешевше","Це дорожче"],"Slightly."),
  ("It's twice as expensive.","Прослухайте. Що каже людина?",["Це вдвічі дорожче","Це вдвічі дешевше","Це трохи дорожче"],"Twice as."),
  ("I don't like it either.","Прослухайте. Що каже людина?",["Їй це теж не подобається","Їй це дуже подобається","Вона це купила"],"Either.")],
 [("It's ___ cheaper.",["slightly","twice","either"],"Slightly."),
  ("It's ___ bigger.",["even","as","half"],"Even."),
  ("I don't like it ___.",["either","too","also"],"Either у запереченні.")],
 ("Що означає half as?",["удвічі менше","удвічі більше","трохи"],"Half as — удвічі менше."),
 ("Це вдвічі дорожче.",["It's","twice","as","expensive"],["half","more"],"It's twice as expensive."),
 ("Це трохи дешевше.",["It's slightly cheaper"],"It's slightly cheaper."),
 ("Is it more expensive?","Вдвічі. Що відповісти?",["Yes, it's twice as expensive.","Yes, it is two as expensive.","Yes, twice expensive it is."],"Yes, it's twice as expensive."))
T(68,5,"Протиставляємо","Протиставити два предмети чи думки.",
 "Whereas — тоді як, on the other hand — з іншого боку, in contrast — навпаки, however — проте, unlike — на відміну від. Приклад: Tea is cheap, whereas coffee is expensive. However, I like both.",
 [W("whereas","/weərˈæz/",C,"тоді як","Tea is cheap, whereas coffee is expensive.","Чай дешевий, а кава дорога."),
  W("on the other hand","/ɒn ði ˌʌðə ˈhænd/",P,"з іншого боку","On the other hand, it's cheaper.","З іншого боку, це дешевше."),
  W("in contrast","/ɪn ˈkɒntrɑːst/",P,"навпаки","In contrast, the bus is slow.","Навпаки, автобус повільний."),
  W("however","/haʊˈevə/",AD,"проте","However, I like both.","Проте мені подобаються обидва."),
  W("unlike","/ʌnˈlaɪk/",P,"на відміну від","Unlike me, he is tall.","На відміну від мене, він високий.")],
 ("Is it more expensive?","Повторимо. Вдвічі. Що відповісти?",["Yes, it's twice as expensive.","Yes, it is two as expensive.","Yes, twice expensive it is."],"Yes, it's twice as expensive."),
 [("Tea is cheap, whereas coffee is expensive.","Прослухайте. Що дешевше?",["Чай","Кава","Однаково"],"Whereas."),
  ("However, I like both.","Прослухайте. Що каже людина?",["Проте їй подобаються обидва","Їй не подобається жодне","Їй подобається лише чай"],"However."),
  ("Unlike me, he is tall.","Прослухайте. Що каже людина?",["На відміну від неї він високий","Вона вища за нього","Вони однакові"],"Unlike.")],
 [("Tea is cheap, ___ coffee is expensive.",["whereas","unlike","either"],"Whereas — тоді як."),
  ("___, I like both.",["However","Whereas","Either"],"However — проте."),
  ("___ me, he is tall.",["Unlike","Whereas","However"],"Unlike — на відміну від.")],
 ("Що означає on the other hand?",["з іншого боку","тоді як","на відміну від"],"On the other hand — з іншого боку."),
 ("Чай дешевий, а кава дорога.",["Tea","is","cheap","whereas","coffee","is","expensive"],["however","more"],"Tea is cheap whereas coffee is expensive."),
 ("Проте мені подобаються обидва.",["However, I like both"],"However, I like both."),
 ("Which do you prefer?","Чай. Що відповісти?",["I prefer tea. However, coffee is nice too.","I prefer tea however coffee nice.","I prefer tea, whereas however coffee."],"I prefer tea. However, coffee is nice too."))
T(68,6,"Повторення: порівняння","Закріпити порівняння.",
 "Нових слів немає. Повторюємо: -er + than (taller than), форми з -r, подвоєнням і -ier (nicer, hotter, easier), as … as, the same as, different from, similar to, slightly, twice as, whereas, however.",
 [],
 ("Which do you prefer?","Повторимо. Чай. Що відповісти?",["I prefer tea. However, coffee is nice too.","I prefer tea however coffee nice.","I prefer tea, whereas however coffee."],"I prefer tea. However, coffee is nice too."),
 [("My brother is taller than me, but I'm faster.","Прослухайте. Що каже людина?",["Брат вищий, а вона швидша","Вона вища, а брат швидший","Вони однакові"],"Taller, faster."),
  ("This room is slightly larger, whereas that one is nicer.","Прослухайте. Що каже людина?",["Ця кімната трохи більша, а та приємніша","Обидві однакові","Та кімната більша"],"Whereas."),
  ("Unlike mine, your phone is similar to hers.","Прослухайте. Що каже людина?",["На відміну від її телефона, твій схожий на її","Усі телефони різні","Телефон такий самий"],"Unlike, similar.")],
 [("The train is ___ than the bus.",["faster","fast","more fast"],"Faster."),
  ("It's ___ expensive as mine.",["twice as","twice","twice than"],"Twice as."),
  ("Today is ___ than yesterday.",["hotter","hoter","more hot"],"Hotter.")],
 ("Яка форма від easy?",["easier","easyer","more easy"],"Easy — easier."),
 ("Мій брат вищий за мене.",["My","brother","is","taller","than","me"],["tall","as"],"My brother is taller than me."),
 ("Моя сумка така сама, як твоя.",["My bag is the same as yours"],"My bag is the same as yours."),
 ("Which is better?","Ця краща, але дорожча. Що відповісти?",["This one is better, but it's more expensive.","This better, but more expensive it.","This is more good, but expensive more."],"This one is better, but it's more expensive."),
 review=True)
